<script setup lang="ts">
import { onBeforeUnmount,ref,watch } from 'vue'
import { useRouter } from 'vue-router'
import { ApiError,get } from '../api'
const router=useRouter(), q=ref(''), data=ref<any>(), loading=ref(false), error=ref(''); let timer:ReturnType<typeof setTimeout>|undefined, sequence=0
watch(q,value=>{if(timer)clearTimeout(timer);if(!value.trim()){data.value=undefined;error.value='';return}timer=setTimeout(async()=>{const current=++sequence;loading.value=true;error.value='';try{const result=await get(`/search?q=${encodeURIComponent(value.trim())}`);if(current===sequence)data.value=result}catch(e){if(current===sequence)error.value=e instanceof ApiError?e.message:'搜索失败'}finally{if(current===sequence)loading.value=false}},250)});onBeforeUnmount(()=>{if(timer)clearTimeout(timer)})
</script>
<template><div><h1 class="title">搜索</h1><input v-model="q" class="input search-large" autofocus placeholder="项目名称、编号、客户或文件…" aria-label="搜索"/><p v-if="loading" class="subtitle">正在搜索…</p><p v-if="error" class="error" role="alert">{{error}}</p><template v-if="data"><section style="margin-top:34px"><h2 class="section-title">项目 / {{data.projects.length}}</h2><div class="list"><button v-for="p in data.projects" :key="p.id" class="list-row list-button" @click="router.push(`/projects/${p.id}`)"><b>{{p.name}}</b><span class="subtitle">{{p.status==='COMPLETED'?'已完成':'在办'}} · {{p.businessYear}}</span><span class="arrow">→</span></button></div></section><section style="margin-top:34px"><h2 class="section-title">文件 / {{data.documents.length}}</h2><div class="list"><div v-for="d in data.documents" :key="d.id" class="list-row"><b>{{d.originalName}}</b><span class="subtitle">{{d.project}} · {{d.title}}</span></div></div></section><p v-if="!data.projects.length&&!data.documents.length" class="subtitle" style="margin-top:32px">没有找到“{{q}}”。试试客户名、项目编号或年份。</p></template></div></template>
